INSERT INTO `lessons` VALUES
(1,'G1-PAG-01',1,'Pagbasa','Pagbasa 1: Si Ana at ang Bola','10 minuto',22,'Layunin: Matututuhan mo kung sino ang nasa kuwento.\n\nPanimula: Tingnan ang larawan ng batang may bola. Ano kaya ang kaniyang nilalaro?\n\nAralin: Si Ana ay may pulang bola. Nasa bakuran ang bola. Masaya si Ana habang naglalaro.\n\nGawain: Basahin ang kuwento. Hanapin kung sino ang may bola.','Basahin o pakinggan ang maikling kuwento. Pagkatapos, sagutin ang tanong.','Si Ana ay may pulang bola.',NULL,'published','2026-07-03 05:23:57','2026-07-03 05:23:57'),
(2,'G1-WIK-01',1,'Bokabularyo','Bokabularyo 1: Mga Bagay sa Paaralan','10 minuto',22,'Layunin: Makikilala mo ang mga salitang ginagamit sa paaralan.\n\nPanimula: Tingnan ang mga gamit sa iyong mesa o bag.\n\nAralin: Ang lapis ay ginagamit sa pagsulat. Ang aklat ay binabasa. Ang bag ay lalagyan ng gamit. Ang papel ay sinusulatan.\n\nMga salita: lapis, aklat, bag, papel.','Basahin ang mga salita. Piliin ang gamit na ginagamit sa pagsulat.','lapis, aklat, bag, papel',NULL,'published','2026-07-03 05:23:59','2026-07-03 05:23:59'),
(3,'G1-PAN-01',1,'Panitikan','Panitikan 1: Madaling Bugtong','10 minuto',22,'Layunin: Matututuhan mo ang simpleng bugtong.\n\nPanimula: Ang bugtong ay isang palaisipan.\n\nAralin: Maliit na kaibigan, kasama sa eskwela. Ginagamit sa pagsulat, hawak ng bata.\n\nGawain: Hulaan ang sagot sa bugtong.','Basahin o pakinggan ang bugtong. Piliin ang tamang sagot.','Ang sagot sa bugtong ay lapis.',NULL,'published','2026-07-03 05:24:00','2026-07-03 05:24:00'),
(4,'G1-ORA-01',1,'Oral Comm','Komunikasyong Pagsasalita 1: Pagbati at Pagpapakilala','10 minuto',26,'Layunin: Makapagpapakilala ka gamit ang simpleng pangungusap.\n\nPanimula: Kapag may bagong kakilala, maaari tayong bumati.\n\nAralin: Magandang araw. Ako si Ana. Ako ay nasa Unang Baitang.\n\nGawain: Pakinggan muna. Pagkatapos, bigkasin nang malinaw.','Pindutin ang Pakinggan. Ulitin ang pangungusap at i-record ang iyong boses.','Magandang araw. Ako si Ana.',NULL,'published','2026-07-03 05:24:02','2026-07-03 16:08:08'),
(5,'G1-SUL-01',1,'Pagsulat','Pagsulat 1: Payak na Pangungusap','10 minuto',28,'Layunin: Makokopya mo ang isang payak na pangungusap.\n\nPanimula: Ang pangungusap ay nagsasabi ng buong diwa.\n\nAralin: Ako ay masaya.\n\nGawain: Basahin at kopyahin ang pangungusap.','Kopyahin ang pangungusap nang malinaw.','Ako ay masaya.',NULL,'published','2026-07-03 05:24:03','2026-07-03 05:24:03'),
(6,'G2-PAG-01',2,'Pagbasa','Pagbasa 2: Ang Punong Mangga','10 minuto',26,'Layunin: Masasagot mo ang tanong na sino, ano, at saan sa kuwento.\n\nPanimula: May mga punong nagbibigay ng bunga at lilim.\n\nAralin: May malaking puno ng mangga sa bakuran nina Lolo Mario. Tuwing hapon, naglalaro sina Nena at Kiko sa ilalim nito. Isang araw, namitas sila ng hinog na mangga at ibinigay ito kay Lola.\n\nGawain: Basahin ang kuwento at alamin kung saan naglalaro ang mga bata.','Basahin ang kuwento. Sagutin ang tanong pagkatapos.','May malaking puno ng mangga sa bakuran.',NULL,'published','2026-07-03 05:24:04','2026-07-03 05:24:04'),
(7,'G2-WIK-01',2,'Bokabularyo','Bokabularyo 2: Mga Salitang Kilos','10 minuto',26,'Layunin: Makikilala mo ang salitang kilos sa pangungusap.\n\nPanimula: Ang salitang kilos ay nagsasabi ng ginagawa.\n\nAralin: Tumakbo si Ben. Umawit si Maya. Nagbasa si Lira.\n\nGawain: Hanapin ang salitang nagpapakita ng kilos.','Basahin ang pangungusap. Piliin ang salitang kilos.','Nagbasa si Lira.',NULL,'published','2026-07-03 05:24:05','2026-07-03 05:24:05'),
(8,'G2-PAN-01',2,'Panitikan','Panitikan 2: Tula tungkol sa Pamilya','12 minuto',26,'Layunin: Matutukoy mo ang paksa ng maikling tula.\n\nPanimula: Ang tula ay nagpapahayag ng damdamin.\n\nAralin: Ang Aking Pamilya\n\nSa bahay naming maliit,\nmay pagmamahalang tunay.\nSina Nanay at Tatay,\ngabay sa aking buhay.\n\nGawain: Basahin ang tula at tukuyin ang paksa.','Basahin ang tula. Piliin ang paksang tinutukoy nito.','Ang aking pamilya ay mahalaga.',NULL,'published','2026-07-03 05:24:07','2026-07-03 05:24:07'),
(9,'G2-ORA-01',2,'Oral Comm','Komunikasyong Pagsasalita 2: Pagsunod sa Panuto','10 minuto',30,'Layunin: Makasusunod ka sa simple at dalawang hakbang na panuto.\n\nPanimula: Mahalaga ang pakikinig upang makasunod sa panuto.\n\nAralin: Kunin ang lapis at isulat ang iyong pangalan. Buksan ang aklat at basahin ang unang pangungusap.\n\nGawain: Pakinggan ang panuto at sabihin kung ano ang unang gagawin.','Pakinggan ang panuto. Piliin ang unang dapat gawin.','Kukunin ko ang lapis at isusulat ko ang aking pangalan.',NULL,'published','2026-07-03 05:24:08','2026-07-03 16:08:09'),
(10,'G2-SUL-01',2,'Pagsulat','Pagsulat 2: Payak na Pangungusap','12 minuto',32,'Layunin: Makabubuo ka ng payak na pangungusap gamit ang isang salita.\n\nPanimula: Ang pangungusap ay nagsisimula sa malaking titik at nagtatapos sa bantas.\n\nAralin: Salita: paaralan. Halimbawa: Ako ay pumapasok sa paaralan.\n\nGawain: Gumawa ng pangungusap gamit ang ibinigay na salita.','Gamitin ang salita sa isang pangungusap.','Ako ay nagbabasa ng aklat.',NULL,'published','2026-07-03 05:24:09','2026-07-03 05:24:09'),
(11,'G3-PAG-01',3,'Pagbasa','Pagbasa 3: Ang Batang Matulungin','12 minuto',30,'Layunin: Matutukoy mo ang pangunahing ideya ng talata.\n\nPanimula: Ang pangunahing ideya ang pinakamahalagang kaisipan ng binasa.\n\nAralin: Tuwing umaga, tinutulungan ni Carlo ang kaniyang lola sa pagdidilig ng halaman. Pagkatapos ng klase, inaayos niya ang kaniyang gamit at tumutulong sa pagliligpit ng mesa. Masaya si Carlo kapag nakatutulong siya sa kaniyang pamilya.\n\nGawain: Basahin ang talata at tukuyin ang pangunahing ideya.','Basahin ang talata. Piliin ang pangunahing ideya.','Masaya si Carlo kapag nakatutulong siya.',NULL,'published','2026-07-03 05:24:10','2026-07-03 05:24:10'),
(12,'G3-WIK-01',3,'Bokabularyo','Bokabularyo 3: Mga Salitang Naglalarawan','12 minuto',30,'Layunin: Makikilala mo ang salitang naglalarawan.\n\nPanimula: Ang salitang naglalarawan ay nagsasabi ng katangian ng tao, bagay, hayop, lugar, o pangyayari.\n\nAralin: Mabango ang bulaklak. Mataas ang puno. Masipag ang bata.\n\nGawain: Hanapin ang salitang naglalarawan sa pangungusap.','Basahin ang pangungusap. Piliin ang salitang naglalarawan.','Masipag ang bata.',NULL,'published','2026-07-03 05:24:12','2026-07-03 05:24:12'),
(13,'G3-PAN-01',3,'Panitikan','Panitikan 3: Ang Maya at ang Uwak','12 minuto',30,'Layunin: Matutukoy mo ang aral sa isang maikling pabula.\n\nPanimula: Ang pabula ay kuwento na karaniwang hayop ang tauhan at may aral.\n\nAralin: Nakita ng uwak ang maya na nag-iipon ng sanga para sa pugad. \"Bakit ka nagpapagod?\" tanong ng uwak. Sumagot ang maya, \"Naghahanda ako bago dumating ang ulan.\" Hindi nakinig ang uwak. Nang umulan, ligtas ang maya sa pugad, ngunit basa at malamig ang uwak.\n\nGawain: Piliin ang aral ng kuwento.','Basahin ang pabula. Piliin ang aral ng kuwento.','Mahalaga ang paghahanda.',NULL,'published','2026-07-03 05:24:13','2026-07-03 05:24:13'),
(14,'G3-ORA-01',3,'Oral Comm','Komunikasyong Pagsasalita 3: Pagkukuwento ng Karanasan','12 minuto',34,'Layunin: Makapagsasalaysay ka ng maikling karanasan gamit ang dalawa hanggang tatlong pangungusap.\n\nPanimula: Kapag nagkukuwento, sabihin kung saan nangyari, sino ang kasama, at ano ang nangyari.\n\nAralin: Kahapon, pumunta ako sa parke. Kasama ko ang aking kapatid. Masaya kaming naglaro.\n\nGawain: I-record ang iyong boses habang nagsasalaysay ng isang masayang karanasan.','Sabihin ang iyong karanasan gamit ang malinaw na boses.','Kahapon, pumunta ako sa parke.',NULL,'published','2026-07-03 05:24:14','2026-07-03 16:08:09'),
(15,'G3-SUL-01',3,'Pagsulat','Pagsulat 3: Maikling Talata','15 minuto',36,'Layunin: Makasusulat ka ng maikling talata tungkol sa isang paksa.\n\nPanimula: Ang talata ay binubuo ng magkakaugnay na pangungusap.\n\nAralin: Paborito ko ang sinigang. Masarap ito lalo na kapag mainit. Kumakain ako nito kasama ang aking pamilya.\n\nGawain: Sumulat ng tatlong pangungusap tungkol sa iyong paboritong pagkain.','Sumulat ng 3 pangungusap tungkol sa iyong paboritong pagkain.','Paborito ko ang sinigang.',NULL,'published','2026-07-03 05:24:15','2026-07-03 05:24:15'),
(16,'G4-PAG-01',4,'Pagbasa','Pagbasa 4: Pangangalaga sa Tubig','12 minuto',34,'Layunin: Makukuha mo ang mahahalagang detalye mula sa tekstong impormatibo.\n\nPanimula: Ang tekstong impormatibo ay nagbibigay ng kaalaman tungkol sa isang paksa.\n\nAralin: Mahalaga ang tubig sa araw-araw na pamumuhay. Ginagamit natin ito sa pag-inom, pagluluto, paglilinis, at pagdidilig ng halaman. Upang makatipid, isara ang gripo kapag hindi ginagamit. Maaari ring gumamit ng timba sa paghuhugas upang hindi masayang ang tubig.\n\nGawain: Basahin ang teksto at hanapin ang paraan ng pagtitipid ng tubig.','Basahin ang teksto. Sagutin ang tanong tungkol sa detalye.','Isara ang gripo kapag hindi ginagamit.',NULL,'published','2026-07-03 05:24:17','2026-07-03 05:24:17'),
(17,'G4-WIK-01',4,'Bokabularyo','Bokabularyo 4: Kasingkahulugan at Kasalungat','12 minuto',34,'Layunin: Matutukoy mo ang kasingkahulugan at kasalungat ng salita.\n\nPanimula: May mga salitang magkapareho ang kahulugan at may mga salitang magkasalungat.\n\nAralin: Ang kasingkahulugan ay salitang kapareho o malapit ang kahulugan. Ang kasalungat ay salitang kabaligtaran ang kahulugan. Halimbawa: mabilis at matulin; mabilis at mabagal.\n\nGawain: Piliin ang kasalungat ng salita.','Basahin ang salita. Piliin ang kasalungat nito.','Ang kasalungat ng mabilis ay mabagal.',NULL,'published','2026-07-03 05:24:18','2026-07-03 05:24:18'),
(18,'G4-PAN-01',4,'Panitikan','Panitikan 4: Alamat ng Munting Bituin','14 minuto',34,'Layunin: Matutukoy mo ang tauhan, tagpuan, at aral sa alamat.\n\nPanimula: Ang alamat ay kuwentong nagpapaliwanag ng pinagmulan ng isang bagay sa malikhaing paraan.\n\nAralin: Noong unang panahon, may isang batang mahilig tumulong sa mga naliligaw sa gabi. Dala niya ang maliit na ilawan upang makita ng mga tao ang daan. Isang gabi, nawala ang kaniyang ilawan, ngunit nagliwanag ang langit. Mula noon, sinasabing ang kaniyang kabutihan ay naging munting bituin na gumagabay sa gabi.\n\nGawain: Basahin ang alamat at tukuyin ang katangian ng bata.','Basahin ang alamat. Sagutin ang tanong pagkatapos.','Ang munting bituin ay gabay sa dilim.',NULL,'published','2026-07-03 05:24:19','2026-07-03 05:24:19'),
(19,'G4-ORA-01',4,'Oral Comm','Komunikasyong Pagsasalita 4: Pakikipanayam','12 minuto',38,'Layunin: Makabubuo ka ng angkop at magalang na tanong sa pakikipanayam.\n\nPanimula: Ang pakikipanayam ay pagtatanong upang makakuha ng impormasyon.\n\nAralin: Dapat magalang ang tono at malinaw ang tanong. Halimbawa: Magandang araw po. Maaari po ba akong magtanong?\n\nGawain: Piliin ang magalang na tanong sa pakikipanayam.','Basahin ang sitwasyon. Piliin ang angkop na tanong.','Magandang araw po. Maaari po ba akong magtanong?',NULL,'published','2026-07-03 05:24:20','2026-07-03 16:08:09'),
(20,'G4-SUL-01',4,'Pagsulat','Pagsulat 4: Talatang May Paksang Pangungusap','15 minuto',40,'Layunin: Makasusulat ka ng talata na may malinaw na paksang pangungusap.\n\nPanimula: Ang paksang pangungusap ang nagsasabi ng pangunahing ideya ng talata.\n\nAralin: Masaya ang aking paaralan. May mababait akong guro at kaibigan. Natututo ako araw-araw. Mas gusto kong pumasok kapag handa ang aking gamit.\n\nGawain: Sumulat ng apat na pangungusap tungkol sa iyong paaralan.','Sumulat ng 4 na pangungusap tungkol sa iyong paaralan.','Masaya ang aking paaralan.',NULL,'published','2026-07-03 05:24:22','2026-07-03 05:24:22'),
(21,'G5-PAG-01',5,'Pagbasa','Pagbasa 5: Barangay Clean-Up Drive','15 minuto',38,'Layunin: Matutukoy mo ang sanhi at bunga sa binasang teksto.\n\nPanimula: Ang sanhi ang dahilan ng pangyayari. Ang bunga ang naging resulta nito.\n\nAralin: Napansin ng mga residente na dumarami ang basura sa kanal. Dahil dito, bumabaha tuwing malakas ang ulan. Naglunsad ang barangay ng clean-up drive upang linisin ang paligid. Pagkatapos ng gawain, naging mas maayos ang daloy ng tubig at mas malinis ang daan.\n\nGawain: Tukuyin ang bunga ng pagdami ng basura sa kanal.','Basahin ang teksto. Tukuyin ang sanhi at bunga.','Dumarami ang basura kaya bumabaha sa kanal.',NULL,'published','2026-07-03 05:24:23','2026-07-03 05:24:23'),
(22,'G5-WIK-01',5,'Bokabularyo','Bokabularyo 5: Sawikain at Kahulugan','15 minuto',38,'Layunin: Maipaliliwanag mo ang kahulugan ng payak na sawikain.\n\nPanimula: Ang sawikain ay pahayag na hindi tuwirang nagsasabi ng kahulugan.\n\nAralin: Bukal sa loob ang ibig sabihin ay taos-puso o kusang-loob. Butas ang bulsa ang ibig sabihin ay kapos sa pera. Magaan ang kamay ang ibig sabihin ay mabilis manakit.\n\nGawain: Piliin ang kahulugan ng sawikain.','Basahin ang sawikain. Piliin ang kahulugan nito.','Bukal sa loob ang kaniyang pagtulong.',NULL,'published','2026-07-03 05:24:24','2026-07-03 05:24:24'),
(23,'G5-PAN-01',5,'Panitikan','Panitikan 5: Tula ng Bayanihan','15 minuto',38,'Layunin: Matutukoy mo ang mensahe ng tula.\n\nPanimula: Ang tula ay maaaring magpahayag ng pagpapahalaga sa kapwa at pamayanan.\n\nAralin: Bayanihan\n\nKapag may bigat na pasan,\nkamay-kamay ay nagtutulungan.\nSa hirap man o saya,\nkapwa ang laging kasama.\n\nSa munting gawa ng bawat isa,\ngumagaan ang problema.\nBayanihang tunay at tapat,\ndaan sa pamayanang maunlad.\n\nGawain: Tukuyin ang pangunahing mensahe ng tula.','Basahin ang tula. Piliin ang mensahe nito.','Sa bayanihan, tayo ay nagtutulungan.',NULL,'published','2026-07-03 05:24:25','2026-07-03 05:24:25'),
(24,'G5-ORA-01',5,'Oral Comm','Komunikasyong Pagsasalita 5: Pagpapahayag ng Opinyon','15 minuto',42,'Layunin: Makapagpapahayag ka ng sariling opinyon gamit ang magalang na pananalita.\n\nPanimula: Sa pagbibigay ng opinyon, mahalagang malinaw ang paninindigan at may dahilan.\n\nAralin: Maaaring gamitin ang: Para sa akin, Sa aking palagay, Naniniwala ako na. Paksa: Mahalaga ba ang pagbabasa araw-araw?\n\nGawain: Magbigay ng dalawang pangungusap na opinyon tungkol sa pagbabasa.','Basahin ang paksa. I-record ang iyong opinyon.','Para sa akin, mahalaga ang pagbabasa araw-araw.',NULL,'published','2026-07-03 05:24:27','2026-07-03 16:08:09'),
(25,'G5-SUL-01',5,'Pagsulat','Pagsulat 5: Liham Paanyaya','15 minuto',44,'Layunin: Makasusulat ka ng simpleng liham paanyaya.\n\nPanimula: Ang liham paanyaya ay ginagamit upang anyayahan ang isang tao sa isang gawain.\n\nAralin: Mahal kong Kaibigan,\nInaanyayahan kita sa aming palatuntunan sa Biyernes. Gaganapin ito sa silid-aralan sa ika-9 ng umaga. Sana ay makadalo ka.\nLubos na gumagalang,\nLia\n\nGawain: Sumulat ng maikling liham paanyaya para sa isang programa sa paaralan.','Gumawa ng sariling liham paanyaya.','Inaanyayahan kita sa aming palatuntunan.',NULL,'published','2026-07-03 05:24:28','2026-07-03 05:24:28'),
(26,'G6-PAG-01',6,'Pagbasa','Pagbasa 6: Bakit Mahalaga ang Pagbabasa','15 minuto',42,'Layunin: Matutukoy mo ang layunin ng may-akda at pangunahing argumento ng teksto.\n\nPanimula: Ang may-akda ay may layunin sa pagsulat, tulad ng manghikayat, magpaliwanag, o magbigay-impormasyon.\n\nAralin: Mahalaga ang pagbabasa dahil pinalalawak nito ang kaalaman at pag-unawa ng isang mag-aaral. Sa pagbabasa, natututuhan ng bata ang bagong salita, impormasyon, at pananaw. Nakakatulong din ito sa mas mahusay na pagsulat at pagsasalita. Kaya dapat gawing ugali ang pagbabasa araw-araw, kahit ilang minuto lamang.\n\nGawain: Tukuyin ang layunin ng may-akda.','Basahin ang teksto. Tukuyin ang layunin ng may-akda.','Ang pagbabasa ay nagpapalawak ng kaalaman.',NULL,'published','2026-07-03 05:24:29','2026-07-03 05:24:29'),
(27,'G6-WIK-01',6,'Bokabularyo','Bokabularyo 6: Mga Salitang Pang-ugnay','15 minuto',42,'Layunin: Magagamit mo ang pang-ugnay upang malinaw na maipakita ang relasyon ng mga ideya.\n\nPanimula: Ang pang-ugnay ay tumutulong upang magkaugnay ang mga salita, parirala, o pangungusap.\n\nAralin: Ginagamit ang dahil upang magbigay ng dahilan. Ginagamit ang kaya upang ipakita ang bunga. Ginagamit ang ngunit upang ipakita ang pagsalungat. Halimbawa: Nag-aral siya nang mabuti kaya mataas ang kaniyang marka.\n\nGawain: Piliin ang angkop na pang-ugnay.','Basahin ang pangungusap. Piliin ang tamang pang-ugnay.','Naglinis ang mga bata kaya gumanda ang silid-aralan.',NULL,'published','2026-07-03 05:24:30','2026-07-03 05:24:30'),
(28,'G6-PAN-01',6,'Panitikan','Panitikan 6: Maikling Kuwento at Tema','15 minuto',42,'Layunin: Matutukoy mo ang tema ng maikling kuwento.\n\nPanimula: Ang tema ay pangunahing kaisipan o mensahe ng akda.\n\nAralin: Si Mira ay laging nahihiyang magbasa sa harap ng klase. Isang araw, hinikayat siya ng kaniyang guro na subukan kahit isang talata lamang. Nagkamali siya sa unang basa, ngunit hindi siya tumigil. Sa paulit-ulit na pagsasanay, unti-unti siyang naging mas malinaw at tiwala sa sarili.\n\nGawain: Tukuyin ang tema ng kuwento.','Basahin ang kuwento. Piliin ang tema nito.','Nagbubunga ang pagsasanay at tiyaga.',NULL,'published','2026-07-03 05:24:32','2026-07-03 05:24:32'),
(29,'G6-ORA-01',6,'Oral Comm','Komunikasyong Pagsasalita 6: Maikling Talumpati','15 minuto',46,'Layunin: Makapaghahanda ka ng maikling talumpati na may malinaw na mensahe.\n\nPanimula: Ang talumpati ay pagsasalita sa harap ng tagapakinig tungkol sa isang paksa.\n\nAralin: Sa talumpati, mahalaga ang malinaw na simula, katawan, at wakas. Paksa: Bakit mahalaga ang respeto sa paaralan?\n\nGawain: Bumuo at bigkasin ang tatlo hanggang apat na pangungusap tungkol sa respeto.','I-record ang maikling talumpati gamit ang malinaw na boses.','Mahalaga ang respeto upang maging maayos ang ating paaralan.',NULL,'published','2026-07-03 05:24:33','2026-07-03 16:08:09'),
(30,'G6-SUL-01',6,'Pagsulat','Pagsulat 6: Maikling Sanaysay ng Opinyon','18 minuto',48,'Layunin: Makasusulat ka ng maikling sanaysay na nagpapahayag ng opinyon at dahilan.\n\nPanimula: Ang sanaysay ng opinyon ay nagsasabi ng paniniwala ng manunulat at nagbibigay ng paliwanag.\n\nAralin: Paksa: Dapat bang magbasa ang mga mag-aaral araw-araw? Sa pagsulat, gumamit ng panimula, dahilan, at pangwakas na pangungusap.\n\nGawain: Sumulat ng limang pangungusap tungkol sa iyong opinyon.','Sumulat ng maikling sanaysay ng opinyon na may dahilan.','Naniniwala ako na mahalaga ang pagbabasa araw-araw.',NULL,'published','2026-07-03 05:24:34','2026-07-03 05:24:34'),
(31,'LESSON-MR9D7SJV-P2RRI',6,'Pagbasa','Pagsusuri ng Teksto','10 minuto',10,'Layunin:\nBasahin at suriin ang kwento patungkol sa pagong at ang kuneho.\n\nAlamin:\nAng Pagong at ang Kuneho\n\nLesson:\nMatutuklasan kung sino ang nagtagumpay sa karera: ang pagong o ang kuneho?',NULL,'Pag may tiyaga, may nilaga.',2,'published','2026-07-06 15:18:47','2026-07-06 16:12:50'),
